SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(4*10^9);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");
load "work/deg10/next_cases_20261030/C242/geometry/deps/native_group_generators.m";
load "work/deg10/next_cases_20261030/C242/geometry/deps/class_group_direct_RR_checked_v4_fastfb.m";
Y:=MDX1(21,GF(5));C:=Curve(Y);cs:=Cusps(Y);os:=CuspOrbitsQ(Y);assert Genus(C) eq 5;c0:=Support([o:o in os|Degree(o) eq 1][1])[1];
F0,mp:=AlgorithmicFunctionField(FunctionField(C));F:=RationalExtensionRepresentation(F0);coords:=[F!mp(FunctionField(C).i):i in [1,2]];base:=DivisorGroup(F)!FunctionFieldDivisor(Divisor(c0));cdivs:=[DivisorGroup(F)!FunctionFieldDivisor(Divisor(c)):c in cs];
print "C236_CYCLIC21_MODEL_READY",[Degree(c):c in cs],Cputime(tt);
ivs:=ClassGroupAbelianInvariants(F:ReductionDivisor:=base,Proof:=true);assert F`cld`proven;MDProvenClassGroupGenerators(F);G:=F`cld`Cl;ff:=F`cld`ZnToCl;Zn:=Domain(ff);fb:=Reverse([x`place:x in F`cld`fb]);fc:=[ff(Zn.i):i in [1..#fb]];assert Invariants(G) eq [2184,0];print "C236_CYCLIC21_GROUP_PROVEN",#fb,Cputime(tt);
function ER(v) return [[Integers()!x:x in Coefficients(Numerator(v))],[Integers()!x:x in Coefficients(Denominator(v))]];end function;
function EF(v) return [ER(x):x in Eltseq(F!v)];end function;
OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);
function EP(pl) I:=Ideal(pl);return [*Order(I) eq OF select 1 else 0,Degree(pl),[EF(v):v in Basis(I)]*];end function;
A0:=F`cld`A1;pp,ee:=Support(A0);assert #pp eq 1 and ee[1] eq 1;ai:=Index(fb,pp[1]);assert ai gt 0;
flags:=[Order(Ideal(p)) eq OF select 1 else 0:p in fb];degs:=[Degree(p):p in fb];ideals:=[*[EF(v):v in Basis(Ideal(p))]:p in fb*];bp,be:=Support(base);assert #bp eq 1 and be[1] eq 1;
frame:=[*[ER(v):v in Coefficients(DefiningPolynomial(F))],flags,degs,ideals,[Eltseq(v):v in fc],[Eltseq(v):v in Rows(RelationMatrix(G))],[EF(v):v in coords],ai*];
Write("work/deg10/next_cases_20261030/C242/geometry/cyclic21_proven_frame_partial.m",Sprint(frame):Overwrite:=true);
GG,_,phi,witness:=MDClassGroupDirectRRCheckedV4FastFB(F,"work/deg10/next_cases_20261030/C242/geometry/cyclic21_cusp_RR.log");assert GG cmpeq G;
cc:=[];for i in [1..#cdivs] do D:=cdivs[i];Append(~cc,phi(D-Degree(D)*base));print "C236_CYCLIC21_CUSP_CLASS",i,#cdivs,Cputime(tt);end for;
hg:=[];orbcoeff:=[];
for o in os do ps,es:=Support(o);vv:=[0:i in [1..#cs]];for i in [1..#ps] do j:=Index(cs,ps[i]);assert j gt 0;vv[j]+:=es[i];end for;assert &+[vv[i]*Degree(cs[i]):i in [1..#cs]] eq Degree(o);Append(~orbcoeff,vv);Append(~hg,&+[vv[i]*cc[i]:i in [1..#cs]]);end for;
H:=sub<G|hg>;assert Invariants(H) eq [364];QH,qh:=quo<G|H>;assert #TorsionSubgroup(QH) eq 6;
comps:=[*{QH!0}*] cat [*{QH|}:d in [1..6]*];for i in [1..#cs] do w:=Degree(cs[i]);if w le 6 then for d in [w..6] do comps[d+1] join:={z+qh(cc[i]):z in comps[d-w+1]};end for;end if;end for;
out:=frame cat [*[Degree(D):D in cdivs],[Eltseq(v):v in cc],[EP(Support(D)[1]):D in cdivs],EP(bp[1]),[Eltseq(v):v in hg],[[Eltseq(v):v in co]:co in comps],orbcoeff*];
Write("work/deg10/next_cases_20261030/C242/geometry/cyclic21_proven_picard.m",Sprint(out):Overwrite:=true);fprintf witness,"]\n";Flush(witness);
printf "C236_D10_CYCLIC21_PROVEN_COMPLETE G=%o H=%o index=%o complement_sizes=%o factorbase=%o cpu=%o\n",Invariants(G),Invariants(H),#TorsionSubgroup(QH),[#s:s in comps],#fb,Cputime(tt);quit;
